describe( 'RunManager', () => {
	it( 'allows one active run at a time, and a new run once the last one ended', async () => {
		const scripted = scriptedQuery( async function* ( ctx ) {
			await ctx.nextInput();
			yield result();
			await ctx.nextInput();
		} );
		const manager = new RunManager( '/repo', scripted.queryFn );
		const first = manager.start( 'analyze', '4.17.5', '/wpsp-analyze-release 4.17.5' );

		expect( () => manager.start( 'prep', '4.17.5', '/wpsp-prep-release 4.17.5' ) ).toThrow( RunConflictError );

		await waitFor( () => first.status === 'awaiting_reply' );
		expect( () => manager.start( 'prep', '4.17.5', '/x' ) ).toThrow( /analyze run is already in progress/ );

		first.finish();

		const second = manager.start( 'prep', '4.17.5', '/wpsp-prep-release 4.17.5' );

		expect( manager.latest ).toBe( second );
		expect( manager.get( second.id ) ).toBe( second );
		expect( manager.get( first.id ) ).toBeNull();

		second.stop();
	} );
} );

describe( 'forceAskHook', () => {
	function preToolUse( toolName: string, toolInput: unknown ): HookInput {
		return { hook_event_name: 'PreToolUse', tool_name: toolName, tool_input: toolInput, tool_use_id: 't', session_id: 's', transcript_path: '', cwd: '/repo' } as HookInput;
	}

	it( 'forces risky Bash commands to ask, with the reason', async () => {
		expect( await forceAskHook( preToolUse( 'Bash', { command: 'gh pr create --base master' } ) ) ).toEqual( {
			hookSpecificOutput: {
				hookEventName: 'PreToolUse',
				permissionDecision: 'ask',
				permissionDecisionReason: 'Changes a GitHub pull request.',
			},
		} );
	} );

	it( 'forces AskUserQuestion to ask', async () => {
		expect( await forceAskHook( preToolUse( 'AskUserQuestion', QUESTION ) ) ).toMatchObject( {
			hookSpecificOutput: { permissionDecision: 'ask' },
		} );
	} );

	it( 'leaves safe commands, other tools, bad input and other events alone', async () => {
		expect( await forceAskHook( preToolUse( 'Bash', { command: 'git status' } ) ) ).toEqual( {} );
		expect( await forceAskHook( preToolUse( 'Bash', null ) ) ).toEqual( {} );
		expect( await forceAskHook( preToolUse( 'Edit', { file_path: 'x' } ) ) ).toEqual( {} );
		expect( await forceAskHook( { hook_event_name: 'Stop' } as HookInput ) ).toEqual( {} );
	} );
} );

describe( 'InputQueue', () => {
	it( 'delivers queued and later messages in order, then ends on close', async () => {
		const queue = new InputQueue();
		const iterator = queue[ Symbol.asyncIterator ]();

		queue.push( 'one' );

		expect( ( await iterator.next() ).value?.message.content ).toBe( 'one' );

		const pending = iterator.next();
		queue.push( 'two' );

		expect( ( await pending ).value?.message.content ).toBe( 'two' );

		const ended = iterator.next();
		queue.close();

		expect( ( await ended ).done ).toBe( true );
		expect( queue.isClosed ).toBe( true );
		expect( () => queue.push( 'three' ) ).toThrow( /no longer accepts/ );
	} );

	it( 'marks messages as typed by a human', async () => {
		const queue = new InputQueue();
		queue.push( 'hi' );

		expect( ( await queue[ Symbol.asyncIterator ]().next() ).value?.origin ).toEqual( { kind: 'human' } );
	} );
} );
